def cobs_encode(payload: bytes) -> bytes:
    if not payload:
        return b"\x01"

    result = bytearray()
    i = 0
    n = len(payload)

    while i < n:
        if payload[i] == 0:
            # Group ends here, count non-zero bytes since last group start
            count = i
            result.append(count)
            i += 1
        else:
            # Count consecutive non-zero bytes
            count = 0
            while i < n and payload[i] != 0:
                count += 1
                i += 1

            if count == 0:
                # Should not happen if logic above is correct, but handle empty run
                result.append(0)
                continue

            if count == n:
                # No zero byte at end
                result.append(255)
            else:
                # Zero byte follows
                result.append(count)

    return bytes(result)

def cobs_decode(data: bytes) -> bytes:
    if len(data) == 0:
        raise ValueError("Empty input")

    result = bytearray()
    i = 0

    while i < len(data):
        code = data[i]
        i += 1

        if code == 0:
            raise ValueError("Invalid code byte 0")

        if code == 255:
            # Read 254 bytes
            if i + 254 > len(data):
                raise ValueError("Trailing code byte 255 promises missing bytes")
            result.extend(data[i:i+254])
            i += 254
        else:
            # Read code-1 bytes
            count = code - 1
            if i + count > len(data):
                raise ValueError("Group data runs past end of input")
            result.extend(data[i:i+count])
            i += count

    return bytes(result)

