module sync_fifo #(parameter WIDTH = 8, parameter DEPTH = 4)
  (input clk, input rst_n,
   input wr_en, input [WIDTH-1:0] din,
   input rd_en, output reg [WIDTH-1:0] dout,
   output full, output empty);

  reg [WIDTH-1:0] data_array [0:DEPTH-1];
  reg [1:0] read_ptr, write_ptr;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      read_ptr <= 2'b00;
      write_ptr <= 2'b00;
      dout <= 16'b0;
      full <= 1'b0;
      empty <= 1'b1;
    end else begin
      if (wr_en && !full) begin
        data_array[write_ptr] <= din;
        write_ptr <= write_ptr + 2'b1;
      end
      if (rd_en && !empty) begin
        dout <= data_array[read_ptr];
        read_ptr <= read_ptr + 2'b1;
      end
    end
  end

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      full <= 1'b0;
      empty <= 1'b1;
    end else begin
      if (write_ptr == read_ptr) begin
        empty <= 1'b1;
        full <= 1'b0;
      end else if (write_ptr == read_ptr + 2'b1) begin
        empty <= 1'b0;
        full <= 1'b1;
      end else begin
        empty <= 1'b0;
        full <= 1'b0;
      end
    end
  end

endmodule

