double mlp_loss_and_grad(const double* params, int n_in, int n_hidden,
                          const double* X, const double* y, int n_samples,
                          double* grad) {
    int idx = 0;
    double* W1 = params;
    double* b1 = params + n_hidden * n_in;
    double* W2 = b1 + n_hidden;
    double* b2 = W2 + n_hidden;

    double* dW1 = grad;
    double* db1 = grad + n_hidden * n_in;
    double* dW2 = db1 + n_hidden;
    double* db2 = dW2 + n_hidden;

    double total_loss = 0.0;

    for (int s = 0; s < n_samples; s++) {
        double* x = X + s * n_in;
        double* y_s = y + s;

        double* h = new double[n_hidden];
        double* z = new double[n_hidden];
        double* p = new double[n_hidden];
        double* dh = new double[n_hidden];
        double* dz = new double[n_hidden];

        // Forward pass for hidden layer
        for (int j = 0; j < n_hidden; j++) {
            double sum = 0.0;
            for (int k = 0; k < n_in; k++) {
                sum += W1[j * n_in + k] * x[k];
            }
            sum += b1[j];
            z[j] = sum;
            h[j] = tanh(sum);
        }

        // Forward pass for output layer
        double z_out = 0.0;
        for (int j = 0; j < n_hidden; j++) {
            z_out += W2[j] * h[j];
        }
        z_out += b2;
        double p_out = 1.0 / (1.0 + exp(-z_out));

        // Loss
        double loss_s = -(y_s * log(p_out) + (1.0 - y_s) * log(1.0 - p_out));
        total_loss += loss_s;

        // Backward pass for output layer
        double d_loss_dp = y_s / p_out - (1.0 - y_s) / (1.0 - p_out);
        double dz_out = d_loss_dp * p_out * (1.0 - p_out);

        // Gradients for W2 and b2
        for (int j = 0; j < n_hidden; j++) {
            dW2[j] = dz_out * h[j];
        }
        db2 = dz_out;

        // Backward pass for hidden layer
        for (int j = 0; j < n_hidden; j++) {
            double sum_h = 0.0;
            for (int k = 0; k < n_in; k++) {
                sum_h += W1[j * n_in + k] * x[k];
            }
            double d_h = dz_out * (1.0 - h[j] * h[j]);
            dh[j] = d_h;
            for (int k = 0; k < n_in; k++) {
                dW1[j * n_in + k] += d_h * x[k];
            }
            db1[j] += d_h;
        }

        delete[] h;
        delete[] z;
        delete[] p;
        delete[] dh;
    }

    double avg_loss = total_loss / n_samples;

    // Scale gradients by 1/n_samples
    for (int i = 0; i < n_hidden * n_in; i++) dW1[i] /= n_samples;
    for (int i = 0; i < n_hidden; i++) db1[i] /= n_samples;
    for (int i = 0; i < n_hidden; i++) dW2[i] /= n_samples;
    db2 /= n_samples;

    return avg_loss;
}

