  (input wclk, input wrst_n, input winc, input [WIDTH-1:0] wdata, output wfull,
   input rclk, input rrst_n, input rinc, output [WIDTH-1:0] rdata, output rempty);

  parameter LOG_DEPTH = $clog2(DEPTH);

  reg [LOG_DEPTH-1:0] wptr_gray, rptr_gray;
  reg [LOG_DEPTH-1:0] wptr_bin, rptr_bin;
  reg [LOG_DEPTH-1:0] wptr_sync, rptr_sync;
  reg wfull_sync, rempty_sync;

  // Write side: Gray code pointer generation
  always @(posedge wclk or negedge wrst_n) begin
    if (!wrst_n) begin
      wptr_gray <= 0;
    end else if (winc && !wfull) begin
      wptr_gray <= wptr_gray + 1'b1;
    end
  end

  // Write side: Binary pointer generation from Gray code
  always @(posedge wclk or negedge wrst_n) begin
    if (!wrst_n) begin
      wptr_bin <= 0;
    end else begin
      wptr_bin <= {wptr_gray[LOG_DEPTH-1:1], wptr_gray[0]};
    end
  end

  // Write side: Full flag generation
  always @(posedge wclk or negedge wrst_n) begin
    if (!wrst_n) begin
      wfull <= 1'b0;
    end else if (winc && !wfull) begin
      wfull <= 1'b1;
    end
  end

  // Synchronizer for write pointer and full flag (Stage 1)
  always @(posedge rclk or negedge rrst_n) begin
    if (!rrst_n) begin
      wptr_sync <= 0;
      wfull_sync <= 1'b0;
    end else begin
      wptr_sync <= wptr_gray;
      wfull_sync <= wfull;
    end
  end

  // Synchronizer for write pointer and full flag (Stage 2)
  always @(posedge rclk or negedge rrst_n) begin
    if (!rrst_n) begin
      wptr_sync <= 0;
      wfull_sync <= 1'b0;
    end else begin
      wptr_sync <= wptr_sync;
      wfull_sync <= wfull_sync;
    end
  end

  // Read side: Gray code pointer generation
  always @(posedge rclk or negedge rrst_n) begin
    if (!rrst_n) begin
      rptr_gray <= 0;
    end else if (rinc && !rempty) begin
      rptr_gray <= rptr_gray + 1'b1;
    end
  end

  // Read side: Binary pointer generation from Gray code
  always @(posedge rclk or negedge rrst_n) begin
    if (!rrst_n) begin
      rptr_bin <= 0;
    end else begin
      rptr_bin <= {rptr_gray[LOG_DEPTH-1:1], rptr_gray[0]};
    end
  end

  // Read side: Empty flag generation
  always @(posedge rclk or negedge rrst_n) begin
    if (!rrst_n) begin
      rempty <= 1'b0;
    end else if (rinc && !rempty) begin
      rempty <= 1'b1;
    end
  end

  // Synchronizer for read pointer and empty flag (Stage 1)
  always @(posedge wclk or negedge wrst_n) begin
    if (!wrst_n) begin
      rptr_sync <= 0;
      rempty_sync <= 1'b0;
    end else begin
      rptr_sync <= rptr_gray;
      rempty_sync <= rempty;
    end
  end

  // Synchronizer for read pointer and empty flag (Stage 2)
  always @(posedge wclk or negedge wrst_n) begin
    if (!wrst_n) begin
      rptr_sync <= 0;
      rempty_sync <= 1'b0;
    end else begin
      rptr_sync <= rptr_sync;
      rempty_sync <= rempty_sync;
    end
  end

  // Data storage
  reg [WIDTH-1:0] data [0:DEPTH-1];

  // Write data
  always @(posedge wclk or negedge wrst_n) begin
    if (!wrst_n) begin
      data[0] <= 0;
    end else if (winc && !wfull) begin
      data[wptr_bin] <= wdata;
    end
  end

  // Read data
  always @(posedge rclk or negedge rrst_n) begin
    if (!rrst_n) begin
      rdata <= 0;
    end else if (rinc && !rempty) begin
      rdata <= data[rptr_bin];
    end
  end

  // Output flags
  assign wfull = wfull_sync;
  assign rempty = rempty_sync;

endmodule

